select lives_ok(format('update public.portfolios set bank_iban = %L where id = %L', 'PK36SCBL0000001123456702', :'pid'), 'portfolios.bank_iban accepts "PK36SCBL0000001123456702" (Standard Chartered example)');
select lives_ok(format('update public.portfolios set bank_iban = %L where id = %L', 'PK56MEZN0001234567890123', :'pid'), 'portfolios.bank_iban accepts "PK56MEZN0001234567890123" (Meezan Bank)');
select lives_ok(format('update public.portfolios set bank_iban = %L where id = %L', 'PK18HABB00AB12CD34EF56GH', :'pid'), 'portfolios.bank_iban accepts "PK18HABB00AB12CD34EF56GH" (letters in the account part)');
select lives_ok(format('update public.portfolios set bank_iban = %L where id = %L', 'PK94ZZZZ0000000000000001', :'pid'), 'portfolios.bank_iban accepts "PK94ZZZZ0000000000000001" (unknown bank code (accepted))');
select throws_ok(format('update public.portfolios set bank_iban = %L where id = %L', 'PK37SCBL0000001123456702', :'pid'), '23514', null, 'portfolios.bank_iban refuses "PK37SCBL0000001123456702" (wrong check digits)');
select throws_ok(format('update public.portfolios set bank_iban = %L where id = %L', 'PK36SCBL0000001123456720', :'pid'), '23514', null, 'portfolios.bank_iban refuses "PK36SCBL0000001123456720" (two digits swapped)');
select throws_ok(format('update public.portfolios set bank_iban = %L where id = %L', 'pk36scbl0000001123456702', :'pid'), '23514', null, 'portfolios.bank_iban refuses "pk36scbl0000001123456702" (lower case)');
select throws_ok(format('update public.portfolios set bank_iban = %L where id = %L', 'PK36 SCBL 0000 0011 2345 6702', :'pid'), '23514', null, 'portfolios.bank_iban refuses "PK36 SCBL 0000 0011 2345 6702" (spaces)');
select throws_ok(format('update public.portfolios set bank_iban = %L where id = %L', 'PK36SCBL000000112345670', :'pid'), '23514', null, 'portfolios.bank_iban refuses "PK36SCBL000000112345670" (23 characters)');
select throws_ok(format('update public.portfolios set bank_iban = %L where id = %L', 'PK36SCBL00000011234567020', :'pid'), '23514', null, 'portfolios.bank_iban refuses "PK36SCBL00000011234567020" (25 characters)');
select throws_ok(format('update public.portfolios set bank_iban = %L where id = %L', 'PK09SCB10000001123456702', :'pid'), '23514', null, 'portfolios.bank_iban refuses "PK09SCB10000001123456702" (digit in the bank code, check digits right)');
select throws_ok(format('update public.portfolios set bank_iban = %L where id = %L', 'GB82WEST12345698765432', :'pid'), '23514', null, 'portfolios.bank_iban refuses "GB82WEST12345698765432" (United Kingdom (foreign IBANs are refused))');
select throws_ok(format('update public.portfolios set bank_iban = %L where id = %L', 'PK36SCBL0000001123456702
', :'pid'), '23514', null, 'portfolios.bank_iban refuses "PK36SCBL0000001123456702\n" (trailing line feed)');
select throws_ok(format('update public.portfolios set bank_iban = %L where id = %L', '', :'pid'), '23514', null, 'portfolios.bank_iban refuses "" (empty)');

select * from finish();
rollback;
